declare p jsonb := '[{"book":"anna-karenina","id":"russia","collection":"core","name":"Russia","noteHash":"951f6f4b920475ed79173748ceceaa1d","positionSource":"6a8b1b11a287729e92ce88ba3490e0fa05fc2c6c39196eb033b75de6cce044cd","narrativeSource":"9e6a3af469c4744dc9f69d7fc0aab5bc92dacf21e5bfc7a2daa9f62eaa936807","description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Oblonsky''s political opinions about Russia conveniently echo his private difficulties.","it":"Le opinioni politiche di Oblonskij sulla Russia rispecchiano comodamente le sue difficoltà private.","fr":"Les opinions politiques d''Oblonski sur la Russie reflètent commodément ses difficultés privées.","es":"Las opiniones políticas de Oblonski sobre Rusia reflejan convenientemente sus problemas privados."}}},{"book":"anna-karenina","id":"wiesbaden","collection":"core","name":"Wiesbaden","noteHash":"951f6f4b920475ed79173748ceceaa1d","positionSource":"5f292b93e5ff3824a02a3987ba06eba3576660a4003f96037e7224ac65c9e7e1","narrativeSource":"9e6a3af469c4744dc9f69d7fc0aab5bc92dacf21e5bfc7a2daa9f62eaa936807","description":{"status":"reviewed","reviewedAt":"2026-11-04","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Oblonsky reads a newspaper report of Count Beust''s journey to Wiesbaden.","it":"Oblonskij legge sul giornale la notizia del viaggio del conte Beust a Wiesbaden.","fr":"Oblonski lit dans le journal la nouvelle du voyage du comte Beust à Wiesbaden.","es":"Oblonski lee en el periódico la noticia del viaje del conde Beust a Wiesbaden."}}},{"book":"anna-karenina","id":"penza","collection":"core","name":"Penza governorate","noteHash":"951f6f4b920475ed79173748ceceaa1d","positionSource":"fb19d32591f0438350b266ef31ed64386942b7c28eb37af1590dced842cad9bd","narrativeSource":"9e6a3af469c4744dc9f69d7fc0aab5bc92dacf21e5bfc7a2daa9f62eaa936807","description":{"status":"reviewed","review